export enum View {
  HOME = 'HOME',
  CARSPOTTING = 'CARSPOTTING',
  EVENTI = 'EVENTI',
  SPONSOR = 'SPONSOR',
  ADMIN_PANEL = 'ADMIN_PANEL'
}

export enum UserRole {
  USER = 'user',
  ORGANIZER = 'organizer',
  ADMIN = 'admin'
}

export interface User {
  isLoggedIn: boolean;
  username?: string;
  role?: UserRole;
  email?: string;
  id?: string;
}

import { createClient } from '@supabase/supabase-js';

const SUPABASE_URL = 'https://hytprjqtelrzeqprdfuq.supabase.co'; 
const SUPABASE_ANON_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imh5dHByanF0ZWxyemVxcHJkZnVxIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjgwOTc0OTUsImV4cCI6MjA4MzY3MzQ5NX0.Dq9Z8okwTKIKrmpXLcmj53hiUP9S04LcQRecol15Ve4'; 

const supabase = (SUPABASE_URL && SUPABASE_ANON_KEY) 
  ? createClient(SUPABASE_URL, SUPABASE_ANON_KEY) 
  : null;

let forceLocalMode = false;

const STORAGE_KEYS = {
  SESSION: 'rni_session',
  EVENTS: 'rni_local_events',
  SPOTS: 'rni_local_spots',
  USERS: 'rni_local_users',
  SPONSORSHIPS: 'rni_local_sponsorships'
};

const getLocal = (key: string) => {
  const data = localStorage.getItem(key);
  return data ? JSON.parse(data) : [];
};

const setLocal = (key: string, data: any) => {
  localStorage.setItem(key, JSON.stringify(data));
};

export const isCloudMode = !!supabase && !forceLocalMode;

const MASTER_USERNAME = 'TIA_258'; 

export const db = {
  setLocalMode: (val: boolean) => { forceLocalMode = val; },

  users: {
    getAll: async () => {
      if (!supabase || forceLocalMode) return getLocal(STORAGE_KEYS.USERS);
      try {
        const { data, error } = await supabase.from('users').select('*').order('username');
        if (error) throw error;
        return data || [];
      } catch (e) {
        forceLocalMode = true;
        return getLocal(STORAGE_KEYS.USERS);
      }
    },
    create: async (userData: any) => {
      const isMaster = userData.username?.toLowerCase() === MASTER_USERNAME.toLowerCase();
      if (!supabase || forceLocalMode) {
        const users = getLocal(STORAGE_KEYS.USERS);
        const newUser = { ...userData, id: Math.random().toString(36).substr(2, 9), role: isMaster ? 'admin' : (users.length === 0 ? 'admin' : 'user') };
        users.push(newUser);
        setLocal(STORAGE_KEYS.USERS, users);
        return newUser;
      }
      try {
        let role = 'user';
        const { count } = await supabase.from('users').select('*', { count: 'exact', head: true });
        if (count === 0 || isMaster) role = 'admin';
        const { data, error } = await supabase.from('users').insert([{ ...userData, role }]).select();
        if (error) throw error;
        return data[0];
      } catch (e) {
        forceLocalMode = true;
        return db.users.create(userData);
      }
    },
    findByUsername: async (identifier: string) => {
      if (!supabase || forceLocalMode) {
        const users = getLocal(STORAGE_KEYS.USERS);
        return users.find((u: any) => u.username === identifier || u.email === identifier) || null;
      }
      try {
        const { data, error } = await supabase.from('users').select('*').or(`username.eq."${identifier}",email.eq."${identifier}"`).maybeSingle();
        if (error) throw error;
        return data;
      } catch (e) {
        forceLocalMode = true;
        return db.users.findByUsername(identifier);
      }
    },
    updateRole: async (userId: string, newRole: string) => {
      if (!supabase || forceLocalMode) {
        const users = getLocal(STORAGE_KEYS.USERS);
        const idx = users.findIndex((u: any) => u.id === userId);
        if (idx !== -1) {
          users[idx].role = newRole;
          setLocal(STORAGE_KEYS.USERS, users);
        }
        return;
      }
      await supabase.from('users').update({ role: newRole }).eq('id', userId);
    },
    update: async (userId: string, updates: any) => {
      if (!supabase || forceLocalMode) {
        const users = getLocal(STORAGE_KEYS.USERS);
        const idx = users.findIndex((u: any) => u.id === userId);
        if (idx !== -1) {
          users[idx] = { ...users[idx], ...updates };
          setLocal(STORAGE_KEYS.USERS, users);
        }
        return users[idx];
      }
      const { data } = await supabase.from('users').update(updates).eq('id', userId).select();
      return data?.[0];
    },
    delete: async (userId: string) => {
      if (!supabase || forceLocalMode) {
        const users = getLocal(STORAGE_KEYS.USERS).filter((u: any) => u.id !== userId);
        setLocal(STORAGE_KEYS.USERS, users);
        return true;
      }
      await supabase.from('users').delete().eq('id', userId);
      return true;
    },
    getById: async (id: string) => {
      if (!supabase || forceLocalMode) return getLocal(STORAGE_KEYS.USERS).find((u: any) => u.id === id);
      const { data } = await supabase.from('users').select('*').eq('id', id).maybeSingle();
      return data;
    }
  },

  events: {
    getAll: async () => {
      if (!supabase || forceLocalMode) return getLocal(STORAGE_KEYS.EVENTS);
      try {
        const { data, error } = await supabase.from('events').select('*').order('date', { ascending: true });
        if (error) throw error;
        return data || [];
      } catch (e) {
        forceLocalMode = true;
        return getLocal(STORAGE_KEYS.EVENTS);
      }
    },
    create: async (eventData: any) => {
      if (!supabase || forceLocalMode) {
        const events = getLocal(STORAGE_KEYS.EVENTS);
        const newEvent = { ...eventData, id: Math.random().toString(36).substr(2, 9), created_at: new Date().toISOString() };
        events.push(newEvent);
        setLocal(STORAGE_KEYS.EVENTS, events);
        return newEvent;
      }
      const { data } = await supabase.from('events').insert([eventData]).select();
      return data?.[0];
    }
  },

  spots: {
    getAll: async () => {
      if (!supabase || forceLocalMode) return getLocal(STORAGE_KEYS.SPOTS);
      try {
        const { data, error } = await supabase.from('spots').select('*').order('created_at', { ascending: false });
        if (error) throw error;
        return data || [];
      } catch (e) {
        forceLocalMode = true;
        return getLocal(STORAGE_KEYS.SPOTS);
      }
    },
    create: async (spotData: any) => {
      if (!supabase || forceLocalMode) {
        const spots = getLocal(STORAGE_KEYS.SPOTS);
        const newSpot = { ...spotData, id: Math.random().toString(36).substr(2, 9), created_at: new Date().toISOString() };
        spots.push(newSpot);
        setLocal(STORAGE_KEYS.SPOTS, spots);
        return newSpot;
      }
      const { data } = await supabase.from('spots').insert([spotData]).select();
      return data?.[0];
    }
  },

  sponsorships: {
    getAll: async () => {
      return getLocal(STORAGE_KEYS.SPONSORSHIPS);
    },
    create: async (data: any) => {
      const list = getLocal(STORAGE_KEYS.SPONSORSHIPS);
      const newItem = { ...data, id: Math.random().toString(36).substr(2, 9), created_at: new Date().toISOString() };
      list.push(newItem);
      setLocal(STORAGE_KEYS.SPONSORSHIPS, list);
      return newItem;
    }
  },

  auth: {
    login: (userData: any) => {
      const session = { 
        username: userData.username, 
        role: userData.role, 
        id: userData.id, 
        email: userData.email,
        timestamp: Date.now() 
      };
      localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(session));
      return session;
    },
    logout: () => localStorage.removeItem(STORAGE_KEYS.SESSION),
    getSession: () => {
      const session = localStorage.getItem(STORAGE_KEYS.SESSION);
      try { return session ? JSON.parse(session) : null; } catch { return null; }
    }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import AuthModal from './components/AuthModal';
import ProfileModal from './components/ProfileModal';
import { View, UserRole, User } from './types';
import { db, isCloudMode } from './services/db';
import { identifyCarFromImage, getSponsorshipStrategy } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [user, setUser] = useState<User>({ isLoggedIn: false });

  const [events, setEvents] = useState<any[]>([]);
  const [spots, setSpots] = useState<any[]>([]);
  const [allUsers, setAllUsers] = useState<any[]>([]);
  const [sponsorships, setSponsorships] = useState<any[]>([]);

  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [scannedCarModel, setScannedCarModel] = useState('');
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [base64ForAI, setBase64ForAI] = useState<string | null>(null);

  const [showEventForm, setShowEventForm] = useState(false);
  const [isGeneratingStrategy, setIsGeneratingStrategy] = useState(false);
  const [aiStrategy, setAiStrategy] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const session = db.auth.getSession();
    if (session && session.username) {
      setUser({ 
        isLoggedIn: true, 
        username: session.username, 
        role: session.role as UserRole,
        id: session.id,
        email: session.email
      });
    }
    loadData();

    return () => {
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, []);

  const loadData = async () => {
    try {
      const [eventsData, spotsData, sponsorData] = await Promise.all([
        db.events.getAll(),
        db.spots.getAll(),
        db.sponsorships.getAll()
      ]);
      setEvents(eventsData || []);
      setSpots(spotsData || []);
      setSponsorships(sponsorData || []);
      setErrorMessage(null);
    } catch (err: any) {
      console.warn("RNI: Cloud Fetch failed, using Local Storage fallback.");
      setErrorMessage("Connessione Cloud non riuscita. Modalità Locale attiva.");
      db.setLocalMode(true);
      loadData(); // Ricarica in modalità locale
    }
  };

  const handleLogin = (userData: any) => {
    if (!userData) return;
    const session = db.auth.login(userData);
    if (session) {
      setUser({ 
        isLoggedIn: true, 
        username: session.username, 
        role: session.role as UserRole,
        id: session.id,
        email: session.email
      });
    }
    setIsAuthModalOpen(false);
  };

  const handleLogout = () => {
    db.auth.logout();
    setUser({ isLoggedIn: false });
    setCurrentView(View.HOME);
    setIsProfileModalOpen(false);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setErrorMessage(null);
    setScannedCarModel('');
    setIsAnalyzing(true);

    if (previewUrl) URL.revokeObjectURL(previewUrl);
    const objectUrl = URL.createObjectURL(file);
    setPreviewUrl(objectUrl);

    const reader = new FileReader();
    reader.onload = async (event) => {
      const fullBase64 = event.target?.result as string;
      setBase64ForAI(fullBase64);

      try {
        const mimeType = file.type || 'image/jpeg';
        const base64Data = fullBase64.split(',')[1];
        const carModel = await identifyCarFromImage(base64Data, mimeType);
        if (carModel && carModel !== 'Sconosciuta') {
          setScannedCarModel(carModel);
        }
      } catch (err: any) {
        setErrorMessage("L'IA ha riscontrato un problema: " + (err.message || "Errore sconosciuto"));
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleAddSpot = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!base64ForAI || isSaving) return;

    setIsSaving(true);
    const formData = new FormData(e.currentTarget);
    const carModelInput = (formData.get('car_model') as string) || scannedCarModel || "Auto Sconosciuta";

    const newSpot = {
      car_model: carModelInput,
      location: "Nord Italia",
      spotted_by: user.username || 'Anonimo',
      image_data: base64ForAI,
      created_at: new Date().toISOString()
    };

    try {
      const savedSpot = await db.spots.create(newSpot);
      setSpots(prev => [savedSpot, ...prev]);
      setPreviewUrl(null);
      setBase64ForAI(null);
      setScannedCarModel('');
    } catch (err) {
      alert("Errore durante il salvataggio dello spot.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleCreateEvent = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const eventData = {
      title: formData.get('title'),
      date: formData.get('date'),
      location: formData.get('location'),
      description: formData.get('description'),
      created_by: user.id
    };

    try {
      const newEvent = await db.events.create(eventData);
      setEvents(prev => [newEvent, ...prev].sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime()));
      setShowEventForm(false);
    } catch (err) {
      alert("Errore nella creazione dell'evento.");
    }
  };

  const handleSubmitSponsorship = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const sponsorData = {
      brand: formData.get('brand'),
      event_target: formData.get('event_target'),
      proposal: formData.get('proposal'),
      contact: formData.get('contact'),
      user_id: user.id || 'anonymous'
    };

    try {
      const newSponsorship = await db.sponsorships.create(sponsorData);
      setSponsorships(prev => [newSponsorship, ...prev]);
      alert("Proposta inviata con successo! Verrai ricontattato presto.");
      e.currentTarget.reset();
      setAiStrategy(null);
    } catch (err) {
      alert("Errore nell'invio della proposta.");
    }
  };

  const handleGenerateStrategy = async (e: React.MouseEvent) => {
    const form = (e.target as HTMLElement).closest('form') as HTMLFormElement;
    const proposal = form.querySelector('textarea[name="proposal"]') as HTMLTextAreaElement;
    if (!proposal.value) {
      alert("Inserisci una descrizione della proposta per generare una strategia AI.");
      return;
    }
    setIsGeneratingStrategy(true);
    try {
      const strategy = await getSponsorshipStrategy(proposal.value);
      setAiStrategy(strategy);
    } catch (err) {
      setAiStrategy("Impossibile generare strategia al momento.");
    } finally {
      setIsGeneratingStrategy(false);
    }
  };

  return (
    <div className="min-h-screen bg-dark-bg text-light-gray font-sans selection:bg-brick-red selection:text-white">
      <Header 
        onOpenAuth={() => setIsAuthModalOpen(true)} 
        onLogout={handleLogout}
        onOpenProfile={() => setIsProfileModalOpen(true)}
        user={user}
        onNavigateHome={() => {
          setCurrentView(View.HOME);
          setShowEventForm(false);
        }}
        onOpenAdmin={() => {
          setCurrentView(View.ADMIN_PANEL);
          if (user.role === UserRole.ADMIN) db.users.getAll().then(setAllUsers);
        }}
      />

      <main className="pt-24 pb-24 px-4 md:px-8 max-w-7xl mx-auto">
        {errorMessage && (
          <div className="mb-8 p-3 bg-orange-500/10 border border-orange-500/30 text-orange-500 text-center text-[9px] font-bold uppercase tracking-widest animate-pulse">
            {errorMessage}
          </div>
        )}

        {currentView === View.HOME && (
          <div className="animate-in fade-in zoom-in duration-500">
            <div className="text-center mb-12">
              <p className="text-brick-red uppercase tracking-[0.5em] text-[10px] font-bold mb-4">Official Community</p>
              <h2 className="text-2xl md:text-4xl text-white font-brand tracking-tighter mb-4">
                RADUNI NORD ITALIA
              </h2>
              <div className="h-1 w-20 bg-brick-red mx-auto mb-8"></div>
              <p className="max-w-xl mx-auto text-sm text-gray-500 italic">
                La piattaforma numero uno per la gestione e la sponsorizzazione di eventi automotive nel Nord Italia.
              </p>
            </div>
            <Hero onSelectView={(view) => setCurrentView(view)} />
          </div>
        )}

        {currentView === View.SPONSOR && (
          <div className="py-4 animate-in fade-in duration-500 max-w-5xl mx-auto">
             <div className="flex justify-between items-center mb-12 border-b border-gray-900 pb-6">
              <h2 className="text-4xl font-brand text-white italic tracking-tighter">SPONSOR<span className="text-brick-red">SHIP</span></h2>
              <button onClick={() => setCurrentView(View.HOME)} className="text-[10px] font-bold text-gray-600 hover:text-white uppercase tracking-widest border border-gray-800 px-4 py-2 transition-colors">Torna Home</button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
              <div className="bg-panel-gray border border-gray-800 p-8 shadow-2xl">
                <h3 className="text-brick-red text-[11px] font-bold uppercase tracking-[0.5em] mb-8">Invia Proposta</h3>
                <form onSubmit={handleSubmitSponsorship} className="space-y-6">
                  <InputField label="Brand / Azienda" name="brand" placeholder="Es: Akrapovič Italia" required />
                  <InputField label="Evento Target" name="event_target" placeholder="Es: Supercar Meeting 2025" required />
                  <div className="space-y-2">
                    <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-[0.2em]">Descrizione Proposta</label>
                    <textarea 
                      name="proposal" 
                      className="w-full bg-black border border-gray-800 p-4 text-white text-sm outline-none focus:border-brick-red resize-none min-h-[150px]" 
                      placeholder="Descrivi cosa offri e cosa cerchi..."
                      required
                    ></textarea>
                  </div>
                  <InputField label="Contatto Email / Tel" name="contact" placeholder="Email o numero di telefono" required />

                  <div className="flex gap-4">
                    <button 
                      type="button" 
                      onClick={handleGenerateStrategy}
                      disabled={isGeneratingStrategy}
                      className="flex-1 border border-gray-700 text-gray-400 py-4 text-[9px] font-bold uppercase tracking-widest hover:border-brick-red hover:text-white transition-all flex items-center justify-center gap-2"
                    >
                      {isGeneratingStrategy ? 'IA sta pensando...' : 'Suggerimento AI'}
                    </button>
                    <button type="submit" className="flex-1 bg-brick-red text-white py-4 text-xs font-bold uppercase tracking-widest hover:brightness-110 transition-all shadow-lg shadow-brick-red/20">Invia Proposta</button>
                  </div>
                </form>
              </div>

              <div className="space-y-8">
                <div className="bg-black/40 border border-gray-900 p-8">
                  <h3 className="text-white text-[11px] font-bold uppercase tracking-[0.5em] mb-4">Perchè collaborare con RNI?</h3>
                  <ul className="space-y-4 text-sm text-gray-500">
                    <li className="flex gap-3"><span className="text-brick-red">01</span> Audience altamente targettizzata nel settore tuning & supercar.</li>
                    <li className="flex gap-3"><span className="text-brick-red">02</span> Visibilità garantita sui nostri canali social (IG/TikTok).</li>
                    <li className="flex gap-3"><span className="text-brick-red">03</span> Supporto logistico e organizzativo per stand in loco.</li>
                  </ul>
                </div>

                {aiStrategy && (
                  <div className="bg-brick-red/5 border border-brick-red/20 p-8 animate-in slide-in-from-right-4">
                    <h3 className="text-brick-red text-[10px] font-bold uppercase tracking-[0.4em] mb-4">Strategia Consigliata (Gemini AI)</h3>
                    <div className="text-xs text-gray-400 leading-relaxed whitespace-pre-wrap italic">
                      {aiStrategy}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {currentView === View.CARSPOTTING && (
          <div className="py-4 animate-in fade-in duration-500 max-w-5xl mx-auto">
            <div className="flex justify-between items-center mb-12 border-b border-gray-900 pb-6">
              <h2 className="text-4xl font-brand text-white italic tracking-tighter">SPOT<span className="text-brick-red">TING</span></h2>
              <button onClick={() => setCurrentView(View.HOME)} className="text-[10px] font-bold text-gray-600 hover:text-white uppercase tracking-widest border border-gray-800 px-4 py-2 transition-colors">Torna Home</button>
            </div>

            {user.isLoggedIn ? (
              <div className="bg-panel-gray border border-gray-800 p-8 mb-16 shadow-2xl relative overflow-hidden">
                <div className="mb-8">
                  <div className="relative w-full aspect-video md:aspect-[21/9] bg-black border border-gray-800 flex items-center justify-center overflow-hidden">
                    {previewUrl ? (
                      <>
                        <img 
                          src={previewUrl} 
                          alt="Preview" 
                          className={`w-full h-full object-contain transition-opacity duration-300 ${isAnalyzing ? 'opacity-30' : 'opacity-100'}`}
                        />
                        {isAnalyzing && (
                          <div className="absolute inset-0 flex flex-col items-center justify-center z-10 bg-black/40 backdrop-blur-sm">
                             <div className="w-12 h-12 border-4 border-brick-red/20 border-t-brick-red rounded-full animate-spin mb-4"></div>
                             <p className="text-[10px] font-bold text-white uppercase tracking-[0.4em]">Analisi AI in corso...</p>
                          </div>
                        )}
                        <button 
                          type="button"
                          onClick={() => { setPreviewUrl(null); setBase64ForAI(null); setScannedCarModel(''); }}
                          className="absolute top-6 right-6 bg-brick-red text-white p-3 hover:scale-110 transition-transform z-20"
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                        </button>
                      </>
                    ) : (
                      <button 
                        type="button"
                        onClick={() => fileInputRef.current?.click()}
                        className="flex flex-col items-center gap-4 group px-12 py-20"
                      >
                        <div className="w-16 h-16 rounded-full border border-gray-800 flex items-center justify-center group-hover:border-brick-red transition-all">
                          <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#b03a2e" strokeWidth="1.5"><path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"/><circle cx="12" cy="13" r="3"/></svg>
                        </div>
                        <span className="text-[11px] font-bold uppercase tracking-[0.5em] text-gray-500 group-hover:text-white transition-colors">Carica Foto Avvistamento</span>
                      </button>
                    )}
                  </div>
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
                </div>

                <form onSubmit={handleAddSpot} className="flex flex-col md:flex-row gap-4">
                  <div className="flex-1 relative">
                    <input 
                      name="car_model" 
                      placeholder="Modello auto..." 
                      value={scannedCarModel}
