import React, { useState } from 'react';
import { db, isCloudMode } from '../services/db';

interface AuthModalProps {
  onClose: () => void;
  onLogin: (userData: any) => void;
}

type AuthMode = 'login' | 'register' | 'organizer';

const AuthModal: React.FC<AuthModalProps> = ({ onClose, onLogin }) => {
  const [mode, setMode] = useState<AuthMode>('login');
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    identifier: '',
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
    orgName: '',
    phoneNumber: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
    setSuccess('');
  };

  const getErrorMessage = (err: any): string => {
    if (!err) return "Errore ignoto";
    if (typeof err === 'string') return err;
    if (err.message && typeof err.message === 'string') return err.message;
    if (err.error_description) return err.error_description;
    if (err.code) return `Errore DB (${err.code}): ${err.message || 'Controlla lo schema cache'}`;

    return "Errore di connessione o schema non valido.";
  };

  const handleResetDatabase = async () => {
    const confirmation = window.confirm("ATTENZIONE: Stai per eliminare TUTTI gli utenti dal database. Questa operazione è definitiva. Vuoi continuare?");
    if (!confirmation) return;

    setIsLoading(true);
    setError('');
    try {
      await db.users.dangerouslyClearAll();
      setSuccess("Database pulito correttamente. Ora puoi registrare un nuovo account master.");
      setMode('register');
    } catch (err: any) {
      console.error("Reset Error:", err);
      setError(getErrorMessage(err));
    } finally {
      setIsLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');
    setSuccess('');

    try {
      if (mode === 'login') {
        const user = await db.users.findByUsername(formData.identifier);
        if (user && user.password === formData.password) {
          onLogin(user);
        } else {
          if (formData.identifier.toLowerCase() === 'tia_258' && !user) {
            setError('Account Master non trovato in questo database. Vai su "REGISTRATI" per crearlo.');
          } else {
            setError('Credenziali non valide. Controlla username e password.');
          }
        }
      } else if (mode === 'register') {
        if (formData.password !== formData.confirmPassword) {
          setError('Le password non coincidono.');
          setIsLoading(false);
          return;
        }

        const isMaster = formData.username?.toLowerCase() === 'tia_258';

        if (!isMaster) {
          const existingUser = await db.users.findByUsername(formData.username) || await db.users.findByUsername(formData.email);
          if (existingUser) {
            setError('Account già esistente con questo nome o email.');
            setIsLoading(false);
            return;
          }
        }

        if (formData.username && formData.email && formData.password) {
          const newUser = await db.users.create({
            username: formData.username,
            email: formData.email,
            password: formData.password
          });

          if (newUser) {
            onLogin(newUser);
          } else {
            setError('Errore durante la creazione. Verifica connessione database.');
          }
        } else {
          setError('Compila tutti i campi obbligatori.');
        }
      }
    } catch (err: any) {
      console.error("Submit Error:", err);
      setError(getErrorMessage(err));
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/95 backdrop-blur-md" onClick={onClose}></div>

      <button 
        onClick={onClose}
        className="fixed top-8 left-8 flex items-center gap-3 text-gray-500 hover:text-brick-red transition-all group z-[110] outline-none"
      >
        <div className="transition-transform group-hover:-translate-x-1 duration-300">
          <svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <line x1="19" y1="12" x2="5" y2="12"></line>
            <polyline points="12 19 5 12 12 5"></polyline>
          </svg>
        </div>
        <span className="text-[11px] font-bold uppercase tracking-[0.4em] opacity-0 translate-x-[-10px] group-hover:opacity-100 group-hover:translate-x-0 transition-all duration-300 ease-out">
          Annulla
        </span>
      </button>

      <div className="relative w-full max-w-md animate-in zoom-in duration-300">
        <div className="bg-panel-gray border border-gray-800 p-8 shadow-2xl relative overflow-hidden">
          {/* Badge Database Mode */}
          <div className="absolute top-0 right-0 px-3 py-1 bg-black border-l border-b border-gray-800 flex items-center gap-2">
            <div className={`w-1.5 h-1.5 rounded-full ${isCloudMode ? 'bg-green-500 shadow-[0_0_5px_rgba(34,197,94,0.5)]' : 'bg-orange-500 shadow-[0_0_5px_rgba(249,115,22,0.5)]'}`}></div>
            <span className="text-[7px] font-bold text-gray-600 uppercase tracking-widest">{isCloudMode ? 'Cloud' : 'Local'} DB</span>
          </div>

          <div className="flex justify-between items-center mb-8 border-b border-gray-800 pb-4 mt-2">
            <button 
              onClick={() => { setMode('login'); setError(''); setSuccess(''); }}
              className={`text-xl font-brand transition-colors ${mode === 'login' ? 'text-brick-red' : 'text-gray-600 hover:text-gray-400'}`}
              disabled={isLoading}
            >
              ACCEDI
            </button>
            <button 
              onClick={() => { setMode('register'); setError(''); setSuccess(''); }}
              className={`text-xl font-brand transition-colors ${mode === 'register' ? 'text-brick-red' : 'text-gray-600 hover:text-gray-400'}`}
              disabled={isLoading}
            >
              REGISTRATI
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            {error && (
              <div className="bg-brick-red/10 border border-brick-red/30 p-4 text-brick-red text-[11px] font-bold text-center uppercase tracking-[0.1em] leading-relaxed">
                {error}
              </div>
            )}

            {success && (
              <div className="bg-green-500/10 border border-green-500/30 p-3 text-green-500 text-[10px] font-bold text-center uppercase tracking-[0.2em]">
                {success}
              </div>
            )}

            {mode === 'login' ? (
              <>
                <InputField label="Username o Email" name="identifier" value={formData.identifier} onChange={handleInputChange} placeholder="Esempio: TIA_258" disabled={isLoading} />
                <InputField label="Password" name="password" type="password" value={formData.password} onChange={handleInputChange} placeholder="••••••••" disabled={isLoading} />
              </>
            ) : (
              <>
                <InputField label="Username scelto" name="username" value={formData.username} onChange={handleInputChange} placeholder="Esempio: TIA_258" disabled={isLoading} />
                <InputField label="Email valida" name="email" type="email" value={formData.email} onChange={handleInputChange} placeholder="nome@esempio.it" disabled={isLoading} />
                <div className="grid grid-cols-2 gap-3">
                  <InputField label="Password" name="password" type="password" value={formData.password} onChange={handleInputChange} placeholder="••••" disabled={isLoading} />
                  <InputField label="Ripeti" name="confirmPassword" type="password" value={formData.confirmPassword} onChange={handleInputChange} placeholder="••••" disabled={isLoading} />
                </div>
              </>
            )}

            <button 
              type="submit"
              disabled={isLoading}
              className={`w-full bg-brick-red text-white py-4 font-bold hover:bg-brick-red/90 transition-all active:scale-[0.98] mt-4 tracking-[0.2em] text-sm flex items-center justify-center gap-2 ${isLoading ? 'opacity-70 cursor-wait' : ''}`}
            >
              {isLoading && (
                <svg className="animate-spin h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              )}
              {mode === 'login' ? 'ACCEDI ORA' : 'CREA PROFILO'}
            </button>
          </form>

          {mode === 'register' && (
            <div className="mt-12 pt-6 border-t border-gray-900 flex flex-col items-center gap-4">
               <p className="text-[9px] text-gray-700 uppercase tracking-widest text-center">Gestione Database</p>
               <button 
                onClick={handleResetDatabase}
                type="button"
                disabled={isLoading}
                className="text-gray-800 hover:text-brick-red text-[8px] font-bold uppercase tracking-[0.4em] transition-colors border border-transparent hover:border-brick-red/20 px-4 py-2"
               >
                 [ Svuota Tabella Utenti ]
               </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const InputField = ({ label, type = 'text', ...props }: any) => {
  const [showPassword, setShowPassword] = useState(false);
