import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import AuthModal from './components/AuthModal';
import ProfileModal from './components/ProfileModal';
import { View, UserRole, User } from './types';
import { db, isCloudMode } from './services/db';
import { identifyCarFromImage } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [user, setUser] = useState<User>({ isLoggedIn: false });

  const [events, setEvents] = useState<any[]>([]);
  const [spots, setSpots] = useState<any[]>([]);
  const [allUsers, setAllUsers] = useState<any[]>([]);

  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [scannedCarModel, setScannedCarModel] = useState('');
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [base64ForAI, setBase64ForAI] = useState<string | null>(null);

  const [showEventForm, setShowEventForm] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const session = db.auth.getSession();
    if (session && session.username) {
      setUser({ 
        isLoggedIn: true, 
        username: session.username, 
        role: session.role as UserRole,
        id: session.id,
        email: session.email
      });
    }
    loadData();

    return () => {
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, []);

  const loadData = async () => {
    try {
      const [eventsData, spotsData] = await Promise.all([
        db.events.getAll(),
        db.spots.getAll()
      ]);
      setEvents(eventsData || []);
      setSpots(spotsData || []);
      setErrorMessage(null);
    } catch (err: any) {
      console.warn("RNI: Cloud Fetch failed, using Local Storage fallback.");
      setErrorMessage("Connessione Cloud non riuscita. Modalità Locale attiva.");
      db.setLocalMode(true);
      loadData();
    }
  };

  const handleLogin = (userData: any) => {
    if (!userData) return;
    const session = db.auth.login(userData);
    if (session) {
      setUser({ 
        isLoggedIn: true, 
        username: session.username, 
        role: session.role as UserRole,
        id: session.id,
        email: session.email
      });
    }
    setIsAuthModalOpen(false);
  };

  const handleLogout = () => {
    db.auth.logout();
    setUser({ isLoggedIn: false });
    setCurrentView(View.HOME);
    setIsProfileModalOpen(false);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setErrorMessage(null);
    setScannedCarModel('');
    setIsAnalyzing(true);

    if (previewUrl) URL.revokeObjectURL(previewUrl);
    const objectUrl = URL.createObjectURL(file);
    setPreviewUrl(objectUrl);

    const reader = new FileReader();
    reader.onload = async (event) => {
      const fullBase64 = event.target?.result as string;
      setBase64ForAI(fullBase64);

      try {
        const mimeType = file.type || 'image/jpeg';
        const base64Data = fullBase64.split(',')[1];
        const carModel = await identifyCarFromImage(base64Data, mimeType);
        if (carModel && carModel !== 'Sconosciuta') {
          setScannedCarModel(carModel);
        }
      } catch (err: any) {
        setErrorMessage("L'IA ha riscontrato un problema: " + (err.message || "Errore sconosciuto"));
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleAddSpot = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!base64ForAI || isSaving) return;

    setIsSaving(true);
    const formData = new FormData(e.currentTarget);
    const carModelInput = (formData.get('car_model') as string) || scannedCarModel || "Auto Sconosciuta";

    const newSpot = {
      car_model: carModelInput,
      location: "Nord Italia",
      spotted_by: user.username || 'Anonimo',
      image_data: base64ForAI,
      created_at: new Date().toISOString()
    };

    try {
      const savedSpot = await db.spots.create(newSpot);
      setSpots(prev => [savedSpot, ...prev]);
      setPreviewUrl(null);
      setBase64ForAI(null);
      setScannedCarModel('');
    } catch (err) {
      alert("Errore durante il salvataggio dello spot.");
    } finally {
      setIsSaving(false);
    }
  };

