                        const nextRole = u.role === 'user' ? 'organizer' : (u.role === 'organizer' ? 'admin' : 'user');
                        await db.users.updateRole(u.id, nextRole);
                        db.users.getAll().then(setAllUsers);
                      }}
                      className="text-[9px] font-bold text-brick-red uppercase tracking-widest"
                    >
                      Cambia Ruolo
                    </button>
