import { createClient } from '@supabase/supabase-js';

const SUPABASE_URL = 'https://hytprjqtelrzeqprdfuq.supabase.co'; 
const SUPABASE_ANON_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imh5dHByanF0ZWxyemVxcHJkZnVxIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjgwOTc0OTUsImV4cCI6MjA4MzY3MzQ5NX0.Dq9Z8okwTKIKrmpXLcmj53hiUP9S04LcQRecol15Ve4'; 

const supabase = (SUPABASE_URL && SUPABASE_ANON_KEY) 
  ? createClient(SUPABASE_URL, SUPABASE_ANON_KEY) 
  : null;

let forceLocalMode = false;

const STORAGE_KEYS = {
  SESSION: 'rni_session',
  EVENTS: 'rni_local_events',
  SPOTS: 'rni_local_spots',
  USERS: 'rni_local_users'
};

const MASTER_USERNAME = 'TIA_258'; 

const getLocal = (key: string) => {
  const data = localStorage.getItem(key);
  return data ? JSON.parse(data) : [];
};

const setLocal = (key: string, data: any) => {
  localStorage.setItem(key, JSON.stringify(data));
};

// Funzione helper per garantire che il Master Username sia sempre Admin
const ensureMasterAdmin = (user: any) => {
  if (!user) return null;
  if (user.username && user.username.toLowerCase() === MASTER_USERNAME.toLowerCase()) {
    return { ...user, role: 'admin' };
  }
  return user;
};

export const isCloudMode = !!supabase && !forceLocalMode;

export const db = {
  setLocalMode: (val: boolean) => { forceLocalMode = val; },

  users: {
    getAll: async () => {
      let users = [];
      if (!supabase || forceLocalMode) {
        users = getLocal(STORAGE_KEYS.USERS);
      } else {
        try {
          const { data, error } = await supabase.from('users').select('*').order('username');
          if (error) throw error;
          users = data || [];
        } catch (e) {
          forceLocalMode = true;
          users = getLocal(STORAGE_KEYS.USERS);
        }
      }
      return users.map(ensureMasterAdmin);
    },
    create: async (userData: any) => {
      const isMaster = userData.username?.toLowerCase() === MASTER_USERNAME.toLowerCase();
      if (!supabase || forceLocalMode) {
        const users = getLocal(STORAGE_KEYS.USERS);
        const newUser = { 
          ...userData, 
          id: Math.random().toString(36).substr(2, 9), 
          role: isMaster ? 'admin' : (users.length === 0 ? 'admin' : 'user') 
        };
        users.push(newUser);
        setLocal(STORAGE_KEYS.USERS, users);
        return ensureMasterAdmin(newUser);
      }
      try {
        let role = 'user';
        const { count } = await supabase.from('users').select('*', { count: 'exact', head: true });
        if (count === 0 || isMaster) role = 'admin';
        const { data, error } = await supabase.from('users').insert([{ ...userData, role }]).select();
        if (error) throw error;
        return ensureMasterAdmin(data[0]);
      } catch (e) {
        forceLocalMode = true;
        return db.users.create(userData);
      }
    },
    findByUsername: async (identifier: string) => {
      let user = null;
      if (!supabase || forceLocalMode) {
        const users = getLocal(STORAGE_KEYS.USERS);
        user = users.find((u: any) => u.username === identifier || u.email === identifier) || null;
      } else {
        try {
          const { data, error } = await supabase.from('users').select('*').or(`username.eq."${identifier}",email.eq."${identifier}"`).maybeSingle();
          if (error) throw error;
          user = data;
        } catch (e) {
          forceLocalMode = true;
          return db.users.findByUsername(identifier);
        }
      }
      return ensureMasterAdmin(user);
    },
    updateRole: async (userId: string, newRole: string) => {
      // Non permettiamo di declassare il master se non è lui a volerlo (ma l'enforcement lo protegge comunque)
      if (!supabase || forceLocalMode) {
        const users = getLocal(STORAGE_KEYS.USERS);
        const idx = users.findIndex((u: any) => u.id === userId);
        if (idx !== -1) {
          users[idx].role = newRole;
          setLocal(STORAGE_KEYS.USERS, users);
        }
        return;
      }
      await supabase.from('users').update({ role: newRole }).eq('id', userId);
    },
    update: async (userId: string, updates: any) => {
      let updatedUser = null;
      if (!supabase || forceLocalMode) {
        const users = getLocal(STORAGE_KEYS.USERS);
        const idx = users.findIndex((u: any) => u.id === userId);
        if (idx !== -1) {
          users[idx] = { ...users[idx], ...updates };
          setLocal(STORAGE_KEYS.USERS, users);
          updatedUser = users[idx];
        }
      } else {
        const { data } = await supabase.from('users').update(updates).eq('id', userId).select();
        updatedUser = data?.[0];
      }
      return ensureMasterAdmin(updatedUser);
    },
    delete: async (userId: string) => {
      if (!supabase || forceLocalMode) {
        const users = getLocal(STORAGE_KEYS.USERS).filter((u: any) => u.id !== userId);
        setLocal(STORAGE_KEYS.USERS, users);
        return true;
      }
      await supabase.from('users').delete().eq('id', userId);
      return true;
    },
    getById: async (id: string) => {
      let user = null;
      if (!supabase || forceLocalMode) {
        user = getLocal(STORAGE_KEYS.USERS).find((u: any) => u.id === id);
      } else {
        const { data } = await supabase.from('users').select('*').eq('id', id).maybeSingle();
        user = data;
      }
      return ensureMasterAdmin(user);
    },
    dangerouslyClearAll: async () => {
      if (!supabase || forceLocalMode) {
        setLocal(STORAGE_KEYS.USERS, []);
        return true;
      }
      try {
        const { error } = await supabase.from('users').delete().neq('username', '_EMPTY_DB_RESET_');
        if (error) throw error;
        return true;
      } catch (e) {
        forceLocalMode = true;
        setLocal(STORAGE_KEYS.USERS, []);
        return true;
      }
    }
  },

  events: {
    getAll: async () => {
      if (!supabase || forceLocalMode) return getLocal(STORAGE_KEYS.EVENTS);
      try {
        const { data, error } = await supabase.from('events').select('*').order('date', { ascending: true });
        if (error) throw error;
        return data || [];
      } catch (e) {
        forceLocalMode = true;
        return getLocal(STORAGE_KEYS.EVENTS);
      }
    },
    create: async (eventData: any) => {
      if (!supabase || forceLocalMode) {
        const events = getLocal(STORAGE_KEYS.EVENTS);
        const newEvent = { ...eventData, id: Math.random().toString(36).substr(2, 9), created_at: new Date().toISOString() };
        events.push(newEvent);
        setLocal(STORAGE_KEYS.EVENTS, events);
        return newEvent;
      }
      const { data } = await supabase.from('events').insert([eventData]).select();
      return data?.[0];
    }
  },

  spots: {
    getAll: async () => {
      if (!supabase || forceLocalMode) return getLocal(STORAGE_KEYS.SPOTS);
      try {
        const { data, error } = await supabase.from('spots').select('*').order('created_at', { ascending: false });
        if (error) throw error;
        return data || [];
      } catch (e) {
        forceLocalMode = true;
        return getLocal(STORAGE_KEYS.SPOTS);
      }
    },
    create: async (spotData: any) => {
      if (!supabase || forceLocalMode) {
        const spots = getLocal(STORAGE_KEYS.SPOTS);
        const newSpot = { ...spotData, id: Math.random().toString(36).substr(2, 9), created_at: new Date().toISOString() };
        spots.push(newSpot);
        setLocal(STORAGE_KEYS.SPOTS, spots);
        return newSpot;
      }
      const { data } = await supabase.from('spots').insert([spotData]).select();
      return data?.[0];
    }
  },

  auth: {
    login: (userData: any) => {
      const fixedUser = ensureMasterAdmin(userData);
      const session = { 
        username: fixedUser.username, 
        role: fixedUser.role, 
        id: fixedUser.id, 
        email: fixedUser.email,
        timestamp: Date.now() 
      };
      localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(session));
      return session;
    },
    logout: () => localStorage.removeItem(STORAGE_KEYS.SESSION),
    getSession: () => {
      const sessionStr = localStorage.getItem(STORAGE_KEYS.SESSION);
      try { 
        if (!sessionStr) return null;
        const session = JSON.parse(sessionStr);
        // Applichiamo l'enforcement anche alla sessione recuperata
        if (session && session.username && session.username.toLowerCase() === MASTER_USERNAME.toLowerCase()) {
          session.role = 'admin';
        }
        return session;
      } catch { return null; }
    }
  }
};
